import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Venus Chub AI (BYOK Provider)","description":"","frontmatter":{"title":"Venus Chub AI (BYOK Provider)"},"headers":[],"relativePath":"providers/venus.md","filePath":"providers/venus.md"}`),a={name:`providers/venus.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="venus-chub-ai-mode-byok" tabindex="-1">Venus Chub AI (Mode BYOK) <a class="header-anchor" href="#venus-chub-ai-mode-byok" aria-label="Permalink to “Venus Chub AI (Mode BYOK)”">​</a></h1><p><strong>Venus Chub AI</strong> beda dari provider lain di panduan ini — penting dipahami sejak awal: ia bukan penyedia <em>inference</em> murni seperti Gemini atau Groq, melainkan <strong>platform roleplay karakter</strong>. Namanya banyak bentuk — Chub AI, Chub Venus, CharacterHub, atau Venus — tapi semuanya satu brand: <strong>Chub</strong> adalah perpustakaan karakter/kartu komunitas raksasa (plus <em>lorebooks</em>), dan <strong>Venus</strong> adalah chat frontend-nya. Yang relevan untuk BYOK di Mikazuki adalah <strong>model hosted mereka bernama Mars</strong> — suite model <em>uncensored</em> milik Chub yang bisa dipakai lewat API inference Chub. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Angka harga, daftar model hosted, dan aturan free tier Chub bisa berubah kapan saja. Halaman ini mengajarkan <strong>cara</strong> yang benar, bukan daftar angka — angka yang disebut di sini bersumber dari docs resmi Chub saat ditulis, dengan imbauan untuk selalu cek situs resmi <a href="https://chub.ai" target="_blank" rel="noreferrer">chub.ai</a> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Daftar (gratis) di <a href="https://chub.ai" target="_blank" rel="noreferrer">chub.ai</a> — cukup email, tidak perlu kartu kredit untuk membuat akun.</li><li>Buka <strong>Account Settings</strong>, cari bagian token/API (di beberapa referensi tampil sebagai <code>my_stages</code> → tokens).</li><li>Buat <strong>API key/token</strong> baru, lalu salin token yang ditampilkan — key ini dipakai sebagai <em>Bearer token</em> di setiap request.</li></ol><p>Endpoint inference Chub yang menjadi referensi:</p><ul><li><strong>Base URL</strong>: <code>https://inference.chub.ai</code></li><li><strong>Auth</strong>: header <code>Authorization: Bearer &lt;token&gt;</code></li></ul><div class="danger custom-block"><p class="custom-block-title">🔒 Pakai API key resmi, BUKAN reverse proxy</p><p>Ini peringatan yang datang <strong>langsung dari docs resmi Chub sendiri</strong>: jangan memakai <strong>reverse proxy</strong> — Chub menyebutnya &quot;kebalikan dari kebalikannya&quot;. Proxy pihak ketiga bisa <strong>menyimpan (log) percakapanmu</strong> dan bahkan <strong>mencuri key-mu</strong>; kamu tidak tahu apa yang terjadi di belakang layanan tak resmi. Selalu buat <strong>API key resmi milikmu sendiri</strong> dari Account Settings Chub dan pakai itu langsung — prinsip yang sama berlaku di sisi BYOK Mikazuki.</p></div><hr><h2 id="mengaktifkan-venus-chub-di-mikazuki-ai" tabindex="-1">Mengaktifkan Venus Chub di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-venus-chub-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan Venus Chub di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk Venus Chub:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, <strong>pilih entri Venus/Chub bila ada</strong> di daftar provider — jika entri itu tersedia, itu jalur terbaik.</li><li>Jika <strong>tidak ada entri Venus/Chub</strong> di daftar, pakai provider <strong>OpenAI Compatible</strong> dengan: <ul><li><strong>Base URL</strong>: <code>https://inference.chub.ai</code></li><li><strong>API key</strong>: token Chub kamu (<em>Bearer token</em>).</li></ul></li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model hosted akan muncul; <strong>gunakan tombol fetch models / konfigurasi Base URL yang tersedia di pengaturan provider</strong> alih-alih mengetik nama endpoint atau path manual dari ingatan.</li><li>Pilih model (misal model suite <strong>Mars</strong> bila tersedia), atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a>, lalu klik simpan.</li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ Jangan mengarang path API</p><p>Kami tidak mendaftar sub-path chat-completions persis karena bisa berubah dan sulit diverifikasi. Cara yang aman: pilih entri Venus/Chub dari daftar provider Mikazuki bila ada, atau isi Base URL di atas lalu <strong>selalu pakai tombol 🔍 fetch models</strong> agar nama model dan endpoint yang valid datang dari konfigurasi — bukan dari tebakan.</p></div><hr><h2 id="parameter-pengaturan" tabindex="-1">Parameter &amp; Pengaturan <a class="header-anchor" href="#parameter-pengaturan" aria-label="Permalink to “Parameter &amp; Pengaturan”">​</a></h2><p>API inference Chub resmi mengekspos parameter-parameter berikut — dua di antaranya punya aturan pemakaian yang perlu kamu tahu:</p><ul><li><strong>Temperature</strong> — mengatur kekacauan/kreativitas jawaban.</li><li><strong>Presence penalty</strong> dan <strong>Frequency penalty</strong> — mengurangi pengulangan.</li><li><strong>Top K</strong> dan <strong>Top P</strong> — mengatur sampling.</li></ul><div class="danger custom-block"><p class="custom-block-title">⚠️ Temperature vs Top P: pilih salah satu</p><p>Aturan resmi Chub: <strong>Top P dan Temperature diatur hanya salah satu</strong>. Kalau kamu mengubah <strong>Temperature, jangan juga mengubah Top P</strong> — dan sebaliknya. Mengubah keduanya bersamaan justru membuat perilaku sampling tidak terkendali. Di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> Mikazuki, cukup biarkan nilai default <strong>temperature 0.85</strong> dan jangan menyentuh Top P, atau kebalikannya.</p></div><p>Soal konsep prompt: <strong>System prompt</strong> dan <strong>Post-history instructions</strong> itu konsep dari dunia Chub — di Mikazuki keduanya setara dengan <em>system prompt</em> dan <em>flavor</em>. Kalau kamu membimbing gaya karakter dari sisi Chub, petakan konsepnya ke dua tempat setara itu di Mikazuki.</p><hr><h2 id="free-tier-langganan" tabindex="-1">Free Tier &amp; Langganan <a class="header-anchor" href="#free-tier-langganan" aria-label="Permalink to “Free Tier &amp; Langganan”">​</a></h2><p>Model hosted Chub berlapis seperti ini (kualitatif, tanpa angka kuota yang kami kunci):</p><ul><li><strong>Free tier</strong> — membuat akun gratis dan ada akses hosted terbatas: model ber-tier dengan <strong>kuota token/pesan terbatas</strong>. Cukup untuk <strong>mencoba</strong> model Mars dan merasakan kualitasnya, <strong>tidak untuk pemakaian intensif</strong>.</li><li><strong>Langganan Mars</strong> — pada saat ditulis, docs resmi Chub menyebut <strong>$20/bulan</strong> dengan <strong>unlimited messaging</strong> plus akses penuh ke ekosistem Chub (karakter, lorebooks, dan lainnya). Angka ini bisa berubah — <strong>cek situs resmi</strong> sebelum berlangganan.</li></ul><p>Kalau kamu sudah berlangganan Mars dan model Mars <strong>tidak muncul</strong> di daftar fetch models, kemungkinan besar langgananmu tidak aktif atau belum tersinkron — lihat bagian <a href="#troubleshooting">Troubleshooting</a>.</p><hr><h2 id="privasi-data" tabindex="-1">Privasi &amp; Data <a class="header-anchor" href="#privasi-data" aria-label="Permalink to “Privasi &amp; Data”">​</a></h2><div class="danger custom-block"><p class="custom-block-title">🛑 Larangan reverse proxy: pahami dua sisinya</p><ul><li><strong>Dari sisi Chub</strong>: docs resmi Chub sendiri <strong>melarang pemakaian reverse proxy</strong> (iturannya persis kebalikan dari yang diiklankan proxy-proxy itu) dan menganjurkan <strong>API key resmi</strong> — proxy pihak ketiga bisa <strong>nge-log datamu</strong> atau <strong>mencuri key</strong>.</li><li><strong>Dari sisi BYOK Mikazuki</strong>: praktik yang sama berlaku — pakai <strong>key resmi milikmu sendiri</strong>, jangan mentah-mentah menempel key pinjaman/proxy orang lain. Sumber &quot;Empty Response&quot; sering bermula dari sini (lihat Troubleshooting).</li></ul></div><p>Mengenai pelatihan model: docs resmi Chub menyatakan <strong>Mars dilatih TANPA chat pengguna</strong> — data proprietary-nya bukan chat publik maupun privat Chub. Jadi percakapan pribadimu di Venus tidak menjadi bahan baku model berikutnya.</p><p>Satu catatan netral yang menyertai kabar baik itu: Chub adalah <strong>platform sosial/komunitas</strong> — soal chat <strong>publik vs privat di Chub itu sendiri</strong> adalah hal lain dengan aturannya sendiri. Publikasikah kontenmu di sana dengan sadar, dan pisahkan antara kebiasaan berbagi di komunitas dengan kebutuhan privasi roleplay pribadimu.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>&quot;Empty Response received from API&quot;</summary><p>Ini error <strong>khas Chub</strong> yang banyak dikeluh komunitas. Penyebab umumnya tiga: model/sumber inference <strong>belum bayar OK</strong> (kuota free tier habis, atau langganan tidak aktif), <strong>key salah</strong>, atau key-mu ternyata <strong>routing milik pihak lain</strong> (kayak proxy/anak pinjaman). Solusinya berlapis: cek key kamu valid dan milikmu sendiri, pastikan model yang dipilih tersedia untuk tier/langganamu, dan — prinsip yang sudah dibacakan di atas — <strong>pakai key resmi sendiri</strong>, bukan proxy.</p></details><details class="details custom-block"><summary>Error 401 — token salah / expired</summary><p>Token Chub kamu salah eja, terpotong saat salin, atau sudah kedaluwarsa. Buka <strong>Account Settings</strong> di chub.ai, buat <strong>token baru</strong>, lalu tempel ulang di Settings Mikazuki pastikan tanpa spasi yang ikut tersalin.</p></details><details class="details custom-block"><summary>Model Mars tidak muncul di daftar fetch</summary><p>Model hosted Chub <strong>ber-tier</strong> — aksesnya mengikuti langgananmu. Pastikan <strong>langganan Mars aktif</strong> (atau model yang kamu pilih memang termasuk tier free). Setelah itu klik 🔍 <strong>fetch models</strong> ulang; kalau masih kosong, coba model hosted lain untuk memastikan key-nya sendiri berfungsi.</p></details><details class="details custom-block"><summary>Jawaban terpotong / berhenti di tengah</summary><p>Naikkan <code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> agar model punya ruang jawaban lebih besar. Ingat juga aturan dari bagian Parameter: kalau kamu mengatur <strong>Temperature, jangan ikut mengubah Top P</strong> — dan sebaliknya. Mengacak-acak keduanya sekaligus bisa membuat gaya jawaban berubah aneh tanpa bekas yang jelas.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./gemini.html">Google Gemini</a> — panduan padanan untuk provider Gemini.</li><li><a href="./deepseek.html">DeepSeek</a> — panduan padanan untuk provider top-up.</li><li><a href="./systemai.html">System AI</a> — kalau kamu tidak ingin mengurus key dan pembayaran API sendiri.</li></ul>`,39)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};